css:
.d-vr{box-sizing:border-box;width:300px;max-width:100%;height:150px;overflow-x:hidden;overflow-y:auto;border:1px solid var(--line);border-radius:10px;background:var(--bg)}
.d-vr-body{display:flex;flex-direction:column;gap:12px;padding:12px}
.d-vr-card{padding:10px 12px;border:1px solid var(--line);border-radius:6px;background:var(--paper);box-shadow:inset 0 1px 0 #fff5;animation:d-scroll-view-reveal-in cubic-bezier(.2,.75,.25,1) both;animation-timeline:view();animation-range:entry 10% cover 45%}
.d-vr-t{margin:0;font-size:15px;color:var(--ink)}
.d-vr-p{margin:2px 0 0;font-size:11px;line-height:1.6;color:var(--muted)}
.d-vr:focus-visible{outline:1px solid var(--ink);outline-offset:2px}
@keyframes d-scroll-view-reveal-in{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
